#include "player/EatingState.h"
#include <iostream>
namespace{int fail(const char* message){std::cerr<<message<<'\n';return 1;}}
int main(){EatingState eating;EatingContext valid;valid.rightHeld=valid.captured=valid.onGround=valid.canEat=true;valid.selectedSlot=2;valid.selected=ItemStack::food(FoodType::APPLE);eating.start(2,FoodType::APPLE);if(!eating.active()||eating.slot()!=2||!eating.canContinue(valid))return fail("eating did not start");if(eating.update(.8f,true)||eating.update(.79f,true))return fail("eating completed early");if(!eating.update(.01f,true)||eating.active())return fail("eating did not complete at 1.6 seconds");
  auto rejected=[&](EatingContext context){eating.start(2,FoodType::APPLE);const bool result=!eating.canContinue(context);eating.cancel();return result;};
  EatingContext context=valid;context.rightHeld=false;if(!rejected(context))return fail("right-button release was accepted");context=valid;context.captured=false;if(!rejected(context))return fail("capture loss was accepted");context=valid;context.inventoryOpen=true;if(!rejected(context))return fail("open inventory was accepted");context=valid;context.onGround=false;if(!rejected(context))return fail("falling was accepted");context=valid;context.flying=true;if(!rejected(context))return fail("flight was accepted");context=valid;context.sprinting=true;if(!rejected(context))return fail("sprinting was accepted");context=valid;context.canEat=false;if(!rejected(context))return fail("full hunger or death was accepted");context=valid;context.horizontalSpeed=5.02f;if(!rejected(context))return fail("movement above walking speed was accepted");context=valid;context.selectedSlot=1;if(!rejected(context))return fail("slot change was accepted");context=valid;context.selected=ItemStack::block(BlockType::DIRT);if(!rejected(context))return fail("item change was accepted");context=valid;context.horizontalSpeed=5.f;eating.start(2,FoodType::APPLE);if(!eating.canContinue(context))return fail("normal grounded walking was rejected");eating.cancel();if(eating.active()||eating.progress()!=0)return fail("damage/death cancellation failed");return 0;}
